using System;using UnityEngine;
public static class SourceDiagramPhysicsValidation{
 static void Check(bool c,string label){if(!c)throw new Exception("Diagram Physics golden failed: "+label);}
 public static void Run(){var real=SourceDiagramPhysics.Lens(350,124);Check(!real.infinity&&real.magnification<0&&Math.Abs(1/real.distance+1/real.imageDistance-1.0/124)<1e-12,"thinlens equation/default real inverted");var virtual_=SourceDiagramPhysics.Lens(600,124);Check(virtual_.magnification>0&&virtual_.imageDistance<0,"virtual upright");Check(SourceDiagramPhysics.Lens(529,124).infinity,"at focus finite image suppressed");Check(SourceDiagramPhysics.Lens(653,124).infinity,"zero objectdistance no divide by zero");var manifest=JsonUtility.FromJson<CatalogManifest>(Resources.Load<TextAsset>("Catalog/manifest").text);int count=0;foreach(var item in manifest.items){if(string.IsNullOrEmpty(item.diagram_file))continue;count++;var go=new GameObject("SOURCE PHYSICS EDITOR SYNTHETIC");try{var scene=go.AddComponent<CatalogScene>();scene.Configure(item);var d=go.GetComponent<SourceDiagramPhysics>();Check(d.label.text.Contains("no OCR/general MNA/calibration"),"honest scope UI");scene.Spring();Check(d.compare,"source comparison actual binding");scene.Spring();Check(!d.compare,"overlay restoration");scene.Tap();Check(d.playing&&d.stage==1,"actual controller stage/play");scene.Tap();Check(!d.playing&&d.stage==2,"actual pause/stage2");if(d.spec.kind=="optics"){double old=d.objectX;scene.ControlAxes(Vector2.right,Vector2.right,.5f,"editor-synthetic");Check(d.objectX>old&&d.focal>124,"object/focal controls");d.objectX=529;d.focal=124;d.Render();Check(d.label.text.Contains("infinity"),"focus UI");d.Axes(new Vector2(float.NaN,0),Vector2.zero,1);Check(d.objectX==529,"invalid input rejected");}
 else if(d.spec.kind=="circuit"){Check(Math.Abs(d.Current-.2)<1e-12,"100V/300+200ohm");Check(Math.Abs(d.Current*d.r1+d.Current*d.r2-d.voltage)<1e-12,"Kirchhoff drop sum");double power=d.Current*d.Current*(d.r1+d.r2);Check(Math.Abs(power-d.voltage*d.Current)<1e-12,"power conservation");d.voltage=0;Check(d.Current==0,"zero voltage");scene.ControlAxes(Vector2.right,Vector2.one,.5f,"editor-synthetic");Check(d.voltage>0&&d.r1>300&&d.r2>200,"voltage/two resistor controls");}
 else{Check(Vector2.Distance(d.BobPixel,new Vector2(d.spec.centroid[0],d.spec.centroid[1]))<1e-4f,"actual source centroid initial bob");d.damping=0;double energy=d.Energy;for(int i=0;i<100;i++)d.Advance(.1);Check(Math.Abs(d.Energy-energy)<1e-7,"RK4 undamped energy conservation10s");d.Reset();d.damping=.1;double e=d.Energy;for(int i=0;i<20;i++)d.Advance(.1);Check(d.Energy<e,"damped energy decreases");d.Reset();scene.ControlAxes(Vector2.right,Vector2.right,.5f,"editor-synthetic");Check(d.length>1&&Math.Abs(d.initialAngle-(Math.Atan2(d.spec.centroid[0]-259,d.spec.centroid[1]-61)+17.5*Math.PI/180))<1e-10,"length/signed angle controls");}
 scene.Reset();Check(!d.playing&&!d.compare&&d.stage==0&&d.time==0,"scene reset");}finally{UnityEngine.Object.DestroyImmediate(go);}}Check(count==3,"three original figure adapters no duplicate pendulum");Debug.Log("SOURCE PHYSICS GOLDEN PASS: thinlens real/virtual/focus/zero; series current/drop/power; RK4 energy/sourcecentroid; actual scene control/UI editor-synthetic, no physical acceptance");}
}
